const cfg=$('Config').first().json;
const msg=items[0].json;
const text=String(msg.message?.text || msg.text || '').trim();
if(!text) return [];
let topic=text;
const m=text.match(/^(?:превью|preview|thumb)\s*[:\-]\s*(.+)$/i);
if(m) topic=m[1].trim();
if(topic.length<3) return [];
return [{json:{...cfg, topic, chatIdFromMsg: msg.message?.chat?.id || msg.chat?.id || cfg.telegramChatId}}];

const cfg = $('Config').first().json;
const topic = $('Extract Topic').first().json.topic;
const chatId = $('Extract Topic').first().json.chatIdFromMsg || cfg.telegramChatId;
const rawItem = items[0].json;
let content = rawItem.message?.content || rawItem.text || rawItem.output || rawItem.response || '';
if (Array.isArray(rawItem.choices) && rawItem.choices[0]?.message?.content) content = rawItem.choices[0].message.content;
if (typeof content !== 'string') content = JSON.stringify(content);
content = content.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/,'').trim();

let variants = [];
try {
  const parsed = JSON.parse(content);
  variants = Array.isArray(parsed) ? parsed : (parsed.variants || [parsed]);
} catch (e) {
  const m = content.match(/\[[\s\S]*\]/);
  if (!m) throw new Error('AI returned non-JSON: ' + content.slice(0, 400));
  variants = JSON.parse(m[0]);
}

const lines = [];
lines.push(`🎬 THUMBNAIL FACTORY`);
lines.push(`Тема: ${topic}`);
lines.push('');
for (const v of variants.slice(0, 3)) {
  lines.push(`—— Вариант ${v.id || ''} ——`);
  lines.push(`🖼 Текст: ${v.cover_text || ''}`);
  if (v.sub_text) lines.push(`↳ ${v.sub_text}`);
  lines.push(`🎭 Эмоция: ${v.emotion || ''}`);
  lines.push(`🎨 Цвета: ${v.colors || ''}`);
  lines.push(`👁 Сцена: ${v.scene || ''}`);
  lines.push(`👤 Объект: ${v.subject || ''}`);
  lines.push(`💡 Почему клик: ${v.why_clicks || ''}`);
  lines.push(`🧠 Prompt:`);
  lines.push(v.image_prompt_en || '');
  lines.push('');
}
lines.push(`Дальше: prompt → Flux/MJ/SD → текст сверху в Canva 1280×720.`);

return [{ json: { telegramChatId: chatId, topic, variants, text: lines.join('\n') } }];
